using System;using System.Drawing;using System.Windows.Forms;
namespace EanEtikety {
public partial class MainForm {
 void ChooseBarcode(bool primary){var current=Read();using(var form=FeatureForm(primary?"Typ čiarového kódu":"Pridať kód",570,640)){var stack=FeatureStack(form);var search=Input(stack,"Vyhľadať typ kódu","");search.Name="barcodeSearch";var category=Choice(stack,"Kategória",new[]{"Všetky","EAN / UPC","1D","2D","GS1"},0);var list=new ListBox{Height=180,IntegralHeight=false,AccessibleName=Loc.T("Typ kódu"),Name="barcodeFormats"};StackAdd(stack,list);var hint=new Label{AutoSize=true,MaximumSize=new Size(480,0)};StackAdd(stack,hint);var data=Input(stack,"Obsah kódu",primary?(Engine.IsGs1(current)?Gs1.Human(current.ApplicationIdentifiers):current.Ean):"");data.Name="barcodeData";data.Multiline=true;data.Height=85;
  StackAdd(stack,Btn(Loc.T("Vložiť príklad"),delegate{var selected=list.SelectedItem as BarcodeDefinition;if(selected!=null)data.Text=selected.Sample;}));
  Action filter=delegate{list.BeginUpdate();try{var previous=list.SelectedItem;list.Items.Clear();string family=category.SelectedIndex<=0?null:new[]{"","EAN / UPC","1D","2D","GS1"}[category.SelectedIndex];foreach(var entry in BarcodeCatalog.Search(search.Text,family,primary))list.Items.Add(entry);if(previous!=null&&list.Items.Contains(previous))list.SelectedItem=previous;else if(list.Items.Count>0)list.SelectedIndex=0;}finally{list.EndUpdate();}hint.Text=list.SelectedItem==null?"":Loc.T(((BarcodeDefinition)list.SelectedItem).Hint);};list.SelectedIndexChanged+=delegate{hint.Text=list.SelectedItem==null?"":Loc.T(((BarcodeDefinition)list.SelectedItem).Hint);};search.TextChanged+=delegate{filter();};category.SelectedIndexChanged+=delegate{filter();};filter();
  foreach(BarcodeDefinition entry in list.Items)if(entry.MatrixType==null&&entry.Kind==current.Kind&&entry.Gs1==Engine.IsGs1(current)){list.SelectedItem=entry;break;}
  AddAccept(form,stack,delegate{var entry=list.SelectedItem as BarcodeDefinition;if(entry==null)throw new InvalidOperationException(Loc.T("Vyberte typ kódu."));var settings=LabelSettings.Default();settings.Kind=entry.Kind;settings.Ean=data.Text;settings.Gs1Mode=entry.Gs1;if(entry.Gs1)settings.ApplicationIdentifiers=Gs1.Parse(data.Text);
   SymbolItem symbol=null;if(entry.MatrixType!=null){var content=new MatrixContent{Type=entry.MatrixType,Data=data.Text};var matrix=Assets.Matrix(content);double width=Math.Min(40,current.Width-6),height=width*matrix.Height/matrix.Width;if(height>current.Height-6){width*= (current.Height-6)/height;height=current.Height-6;}symbol=new SymbolItem{X=3,Y=3,Width=width,Height=height,Matrix=content};}else{if(!entry.Gs1)Engine.Normalize(settings.Ean,entry.Kind);if(entry.Gs1)Gs1.Payload(settings.ApplicationIdentifiers);settings.BarWidth=Math.Min(current.BarWidth,current.Width-6);symbol=new SymbolItem{X=3,Y=3,Width=settings.BarWidth,Height=Engine.BarcodeHeight(settings),Code=BarcodeContent.From(settings)};}
   ChangeDocument(s=>{if(primary){s.Kind=settings.Kind;s.Ean=settings.Ean;s.Gs1Mode=settings.Gs1Mode;s.ApplicationIdentifiers=settings.ApplicationIdentifiers;}else{if(s.Symbols.Count>=20)throw new InvalidOperationException(Loc.T("Najviac 20 symbolov."));s.Symbols.Add(symbol);}});if(!primary)preview.SelectElement(-3-symbols.Count+1);
  });form.ShowDialog(this);}}
}
}
